export type JourneyCtaType =
  | "audit"
  | "quote"
  | "maintenance"
  | "strategicReview"
  | "similarProject";

const CONTACT_INTENT_PARAMS: Record<JourneyCtaType, string> = {
  audit: "audit",
  quote: "quote",
  maintenance: "maintenance",
  strategicReview: "strategic-review",
  similarProject: "similar-project",
};

const CONTACT_INTENT_HASHES: Record<JourneyCtaType, string> = {
  audit: "#contact-audit",
  quote: "#contact-request-form",
  maintenance: "#contact-request-form",
  strategicReview: "#contact-request-form",
  similarProject: "#contact-request-form",
};

const CONTACT_INTENT_PARAM_TO_TYPE = Object.entries(CONTACT_INTENT_PARAMS).reduce(
  (accumulator, [type, value]) => {
    accumulator[value] = type as JourneyCtaType;
    return accumulator;
  },
  {} as Record<string, JourneyCtaType>
);

export const buildContactIntentPath = (type: JourneyCtaType) =>
  `/contact/?intent=${CONTACT_INTENT_PARAMS[type]}${CONTACT_INTENT_HASHES[type]}`;

export const getContactIntentFromSearch = (
  search?: string
): JourneyCtaType | undefined => {
  if (!search) return undefined;

  const params = new URLSearchParams(search);
  const intent = params.get("intent");

  return intent ? CONTACT_INTENT_PARAM_TO_TYPE[intent] : undefined;
};
