import * as React from "react";
import AppLink from "./AppLink";

export type CaseStudyProofLabels = {
  businessType: string;
  problem: string;
  intervention: string;
  result: string;
};

export type CaseStudyProofItem = {
  client: string;
  businessType: string;
  problem: string;
  intervention: string;
  result: string;
  href?: string;
  ctaLabel?: string;
  eyebrow?: string;
};

type CaseStudyProofGridProps = {
  title: string;
  subtitle?: string;
  labels: CaseStudyProofLabels;
  items: CaseStudyProofItem[];
};

const CaseStudyProofGrid: React.FC<CaseStudyProofGridProps> = ({
  title,
  subtitle,
  labels,
  items,
}) => {
  if (!title || !Array.isArray(items) || items.length === 0) {
    return null;
  }

  return (
    <section className="py-10 sm:py-14">
      <div className="mx-auto w-full max-w-6xl px-4 sm:px-6">
        <div className="mx-auto max-w-4xl text-center">
          <h2 className="text-2xl sm:text-4xl poppins-regular text-verde">
            {title}
          </h2>
          {subtitle ? (
            <p className="mt-4 text-sm sm:text-base text-light/70">{subtitle}</p>
          ) : null}
        </div>

        <div className="mt-8 grid grid-cols-1 gap-4 lg:grid-cols-3">
          {items.map((item, index) => (
            <article
              key={`${item.client}-${index}`}
              className="rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light"
            >
              {item.eyebrow ? (
                <p className="text-xs font-semibold uppercase tracking-[0.14em] text-secondary">
                  {item.eyebrow}
                </p>
              ) : null}

              <h3 className="mt-2 text-lg sm:text-xl font-semibold text-light/90">
                {item.client}
              </h3>

              <div className="mt-4 rounded-xl border border-white/10 bg-white/5 p-4">
                <p className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                  {labels.businessType}
                </p>
                <p className="mt-2 text-sm sm:text-base text-light/85">
                  {item.businessType}
                </p>
              </div>

              <dl className="mt-4 space-y-4">
                <div className="rounded-xl border border-white/10 bg-white/5 p-4">
                  <dt className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                    {labels.problem}
                  </dt>
                  <dd className="mt-2 text-sm sm:text-base text-light/80">
                    {item.problem}
                  </dd>
                </div>

                <div className="rounded-xl border border-white/10 bg-white/5 p-4">
                  <dt className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                    {labels.intervention}
                  </dt>
                  <dd className="mt-2 text-sm sm:text-base text-light/80">
                    {item.intervention}
                  </dd>
                </div>

                <div className="rounded-xl border border-white/10 bg-white/5 p-4">
                  <dt className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                    {labels.result}
                  </dt>
                  <dd className="mt-2 text-sm sm:text-base text-light/80">
                    {item.result}
                  </dd>
                </div>
              </dl>

              {item.href && item.ctaLabel ? (
                <div className="mt-5">
                  <AppLink className="underline text-sm" to={item.href}>
                    {item.ctaLabel}
                  </AppLink>
                </div>
              ) : null}
            </article>
          ))}
        </div>
      </div>
    </section>
  );
};

export default CaseStudyProofGrid;
